begin;
create temp table assertions(label text);grant all on assertions to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
insert into auth.users(id,email,is_anonymous) values
('91000000-0000-4000-8000-000000000001','library-a@qa.invalid',false),('91000000-0000-4000-8000-000000000002','library-b@qa.invalid',false),('91000000-0000-4000-8000-000000000003',null,true);
create temp table library_test(data jsonb);grant all on library_test to authenticated;
insert into library_test values('{"title":"Soal contoh","kind":"cards","items":[{"id":"92000000-0000-4000-8000-000000000001","kind":"card","prompt":"Dua tambah tiga","options":["5","4","3","2"],"key":"A","explanation":"Lima."}]}');
set local role authenticated;set local request.jwt.claims='{"sub":"91000000-0000-4000-8000-000000000001","is_anonymous":false}';
select public.create_class_with_roster('93000000-0000-4000-8000-000000000001','7B',7,3,'pilot');
select public.create_class_with_roster('93000000-0000-4000-8000-000000000002','7C',7,3,'pilot');
select pg_temp.ok(not(public.library_action(jsonb_build_object('action','save','id','94000000-0000-4000-8000-000000000001','revision',0,'ready',true,'document',(select data from library_test))) ? 'error'),'ready collection stored by owner');
select pg_temp.ok((select current_version=1 from public.question_sets where id='94000000-0000-4000-8000-000000000001'),'version one persisted');
select pg_temp.ok(public.library_action(jsonb_build_object('action','save','id','94000000-0000-4000-8000-000000000002','revision',0,'ready',true,'document',jsonb_set((select data from library_test),'{items,0,options}','["5","5","3","2"]'))) ->>'error'='INVALID_INPUT','SQL rejects duplicate options');
select pg_temp.ok(public.library_action(jsonb_build_object('action','save','id','94000000-0000-4000-8000-000000000002','revision',0,'ready',true,'document',(select data from library_test)||'{"nickname":"LOCAL"}')) ->>'error'='INVALID_INPUT','SQL rejects identity injection');
select public.library_action('{"action":"start","id":"95000000-0000-4000-8000-000000000001","classId":"93000000-0000-4000-8000-000000000001","collectionId":"94000000-0000-4000-8000-000000000001","version":1,"date":"2026-09-30","mode":"assessment"}');
select public.library_action('{"action":"start","id":"95000000-0000-4000-8000-000000000002","classId":"93000000-0000-4000-8000-000000000002","collectionId":"94000000-0000-4000-8000-000000000001","version":1,"date":"2026-09-29","mode":"assessment"}');
select pg_temp.ok((select count(*)=2 from public.library_runs),'same immutable version reused across two classes');
select public.library_action('{"action":"start","id":"95000000-0000-4000-8000-000000000001","classId":"93000000-0000-4000-8000-000000000001","collectionId":"94000000-0000-4000-8000-000000000001","version":1,"date":"2026-09-30","mode":"assessment"}');
select pg_temp.ok((select count(*)=2 from public.library_runs),'double start with same id is idempotent');
create temp table submitted as select jsonb_build_object('action','response','id',r.id,'formId',r.form_id,'pageIndex',0,'version',1,'studentId',r.roster->0->'id','answers',jsonb_build_array('A'),'revision',0,'status','received') data from public.library_runs r where r.id='95000000-0000-4000-8000-000000000001';
select pg_temp.ok(public.library_action((select data from submitted)||'{"formId":"96000000-0000-4000-8000-000000000001"}')->>'error'='INVALID_INPUT','wrong form rejected');
select pg_temp.ok(public.library_action((select data from submitted)||'{"pageIndex":1}')->>'error'='INVALID_INPUT','wrong page rejected');
select pg_temp.ok(public.library_action((select data from submitted)||'{"version":2}')->>'error'='INVALID_INPUT','wrong frozen version rejected');
select public.library_action((select data from submitted));select public.library_action((select data from submitted));
select pg_temp.ok((select count(*)=1 and min(correct)=1 and min(revision)=1 from public.library_responses),'server grades trusted key; replay creates one row/revision');
select pg_temp.ok((select count(*)=0 from public.library_responses where run_id='95000000-0000-4000-8000-000000000002'),'7C results do not mix with 7B');
select public.library_action((select data from submitted)||'{"answers":["?"],"revision":1}');
select pg_temp.ok((select revision=2 and correct=0 and answers='["?"]' from public.library_responses),'correction revises; unknown is actual response');
select pg_temp.ok(public.library_action((select data from submitted)||'{"answers":["B"]}')->>'error'='CONFLICT','stale correction rejected');
select public.library_action(jsonb_build_object('action','save','id','94000000-0000-4000-8000-000000000001','revision',1,'ready',true,'document',jsonb_set((select data from library_test),'{items,0,key}','"B"')));
select pg_temp.ok((select document->'items'->0->>'key'='A' from public.question_versions where set_id='94000000-0000-4000-8000-000000000001' and version=1),'old key immutable after editing set');
select pg_temp.ok((select document->'items'->0->>'key'='B' from public.question_versions where set_id='94000000-0000-4000-8000-000000000001' and version=2),'edit creates next version');
select public.library_action(jsonb_build_object('action','roster','classId','93000000-0000-4000-8000-000000000001','studentId',(select data->'studentId' from submitted),'attendanceNumber',9,'active',false));
select pg_temp.ok((select roster->0->>'attendanceNumber'='1' from public.library_runs where id='95000000-0000-4000-8000-000000000001'),'roster attendance snapshot unchanged by rename/archive');
select pg_temp.ok((select count(*)=1 from public.library_responses),'archive retains response');
set local request.jwt.claims='{"sub":"91000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select count(*)=0 from public.library_runs),'second teacher cannot read runs');
select pg_temp.ok((select count(*)=0 from public.library_responses),'second teacher cannot read responses');
select pg_temp.ok(public.library_action('{"action":"detail","id":"95000000-0000-4000-8000-000000000001"}')->>'error'='NOT_FOUND','RPC ownership enforced');
set local request.jwt.claims='{"sub":"91000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select count(*)=0 from public.question_versions),'anonymous board cannot read answer versions');
select pg_temp.ok((select count(*)=0 from public.library_responses),'board cannot read results');
select pg_temp.ok(public.library_action('{"action":"list"}')->>'error'='FORBIDDEN','anonymous board not teacher');
reset role;
select count(*)||' library SQL assertions PASS' from assertions;
rollback;
